    },
    {
      "name": "沈星河",
      "role": "deuteragonist",
      "identity": "失踪三年的学霸，被困在透明层",
      "traits": ["温柔", "执着", "孤独", "聪慧", "深情"],
      "overt_motivation": "陪伴林晚，在她耳边说话（以为她听不见）",
      "covert_motivation": "渴望被她看见、被她记住、被她爱",
      "secret_fear": "害怕她永远看不见自己、害怕被遗忘、害怕自己的陪伴毫无意义",
      "misperception_of_other": "以为林晚听不见自己说话，不知道她偶尔会有感应",
      "hidden_connection": "三年前失踪前就注意过林晚，失踪后一直在透明层陪伴她；她是他在透明层唯一能看见的人"
    }
  ],
  "supporting_characters": [
    {
      "name": "陈雨",
      "function": "阻碍",
      "identity": "林晚的同班同学，霸凌者",
      "description": "表面光鲜的优等生，实际是霸凌林晚的主导者，她的存在让林晚不得不触发规则"
    },
    {
      "name": "苏晴",
      "function": "助力",
      "identity": "林晚唯一的朋友",
